page('franchise.html','Manufacturing & franchise',photo_intro('Manufacturing & Franchise','Explore Nanolite’s T-series plants and the support behind your manufacturing plans.','concrete.jpg')+'<section class="wrap franchise-feature section"><img src="assets/original/pdf-10-198.png" alt="Nanolite production facility"><div><h2>Franchise with us.</h2><p>Join Nanolite’s lightweight concrete manufacturing network. Work with our team on product selection, equipment configuration, production planning and the technical support your operation needs.</p>'+button('Discuss a partnership','request.html?type=plant&product=t5000')+'</div></section><section class="wrap product-list">'+''.join(row(id) for id in ORDER[8:])+'</section>')
roles=json.loads((R/'career-roles.json').read_text(encoding='utf-8'))
body=photo_intro('Careers','Build the equipment. Run the plant. Explore our manufacturing role profiles.','careers-hero.webp')+'<section class="wrap section"><form class="career-filters" role="search"><label>Search roles<input id="role-search" type="search" placeholder="Role, skill or software"></label><label>Specialism<select id="role-team"><option value="">All specialisms</option>'+''.join(f'<option>{e(t)}</option>' for t in dict.fromkeys(r['team'] for r in roles))+'</select></label><label>Career stage<select id="role-level"><option value="">All stages</option><option value="professional">Professional roles</option><option value="early">Early careers</option></select></label><button type="reset" class="text-link">Clear filters</button></form><p id="role-count" aria-live="polite">12 roles</p><div class="roles">'
for i,r in enumerate(roles):
 body+=f'<details class="role" data-team="{e(r["team"])}" data-level="{e(r["level"])}"><summary><span><small>{e(r["team"])}</small>{e(r["title"])}</span><span aria-hidden="true">+</span></summary><div class="role-body"><p class="small">Role profile for manufacturing recruitment. Location and vacancy availability are confirmed by the team.</p><p>{e(r["description"])}</p><h3>Responsibilities</h3><ul>'+''.join(f'<li>{e(x)}</li>' for x in r['responsibilities'])+f'</ul><h3>Qualifications</h3><p>{e(r["qualification"])}</p><h3>Experience</h3><p>{e(r["experience"])}</p><h3>Practical skills</h3><ul>'+''.join(f'<li>{e(x)}</li>' for x in r['skills'])+'</ul><h3>Software & equipment</h3><ul>'+''.join(f'<li>{e(x)}</li>' for x in r['tools'])+'</ul>'+button('Register interest','mailto:management@nanolite.co?subject='+quote('Career interest: '+r['title']))+'</div></details>'
body+='</div><p id="role-empty" hidden>No matching roles. Try another search or clear the filters.</p></section><section class="intro-band"><div class="wrap split"><h2>Why work with NGC?</h2><div><p>Join a global team spanning construction, mining, technology, textiles, agriculture and legal consultancy. Nanolite Group supports learning through internal training, mentorship and collaboration across departments.</p><p>Share your skills and interests with our team. Role profiles describe recruitment specialisms; they do not confirm current vacancies.</p></div></div></section>'
page('careers.html','Careers',body,'<script src="careers.js" defer></script>')
page('investors.html','Investors',photo_intro('Investors','Company information, business activities and investor inquiries.','investors-hero.webp')+'<section class="wrap section"><p class="eyebrow">Historical overview / Company profile</p><h2>Company profile overview</h2><p class="measure">The supplied Nanolite Group profile reports a 75% share of Pakistan’s lightweight construction materials sector as of 2024, with international expansion into the UAE, China and the United States. It also describes projected annual revenue growth of 20–25% across construction, textiles, software, mining and agriculture.</p><p class="small measure">These are historical company-profile statements and projections, not current audited figures or investment forecasts. Contact investor relations for current company information.</p></section><section class="wrap section"><div class="sector-grid"><article><p class="eyebrow">01 / Construction</p><h2>Materials and production</h2><p>Nanolite’s CLC blocks, production plants and franchise model bring materials research into construction.</p><a class="text-link" href="products.html">Explore construction solutions ↗</a></article><article><p class="eyebrow">02 / Global trade</p><h2>Connected industries</h2><p>NanoFarms, NanoLooms and NanoMines extend the group’s activities across agriculture, textiles and mineral exports.</p><a class="text-link" href="https://nanolitegroupofcompanies.com/businesses.html">View group businesses ↗</a></article><article><p class="eyebrow">03 / Technology</p><h2>Digital capabilities</h2><p>NanoTech provides software development and technology consulting to help businesses improve their operations.</p><a class="text-link" href="https://nanolitegroupofcompanies.com/businesses.html#nanotech">Discover NanoTech ↗</a></article></div></section><section class="intro-band"><div class="wrap split"><h2>Speak with investor relations.</h2><div><p>For company information and investment enquiries, contact our team directly.</p>'+button('Contact investor relations','mailto:management@nanolite.co?subject=Investor%20relations%20enquiry')+'</div></div></section>')
privacy_sections=[('Scope and contact','This policy covers the Nanolite Global website and its published preview. For privacy questions, contact management@nanolite.co. It does not replace the separate privacy policy for the Nanolite app.'),('Information you choose to provide','Inquiry and order forms ask for contact details and information about your question, product requirements or project. Please provide only information needed to discuss your request. Do not include passwords, payment-card details or unnecessary sensitive documents.'),('How website forms work','Preparing an inquiry or order review processes the fields in your browser. The current website does not upload these form fields to a form database. Choosing Open email draft passes the reviewed information to your selected email application. Your message reaches Nanolite when you send that email.'),('Hosting and technical information','Cloudflare hosts and protects this website and may process request information, such as IP addresses and browser or connection details, to deliver and secure it. See Cloudflare’s privacy policy for information about its services.'),('Cookies and local storage','The current website code does not set advertising or analytics cookies, use advertising trackers, or store your form entries in local storage. Your browser may cache pages, fonts and media. Hosting security services and external services may have their own practices.'),('Use of correspondence','When you send an email, the information in it is used to handle your inquiry, discuss products or services, prepare quotations and maintain relevant business correspondence. Email providers process messages as part of delivery. Information may also be handled where necessary to meet applicable obligations or address security and disputes.'),('Your choices','You can choose not to complete a form, edit your draft before sending it, or contact us directly. To ask about personal information you have sent to Nanolite, request a correction, or ask for deletion, email management@nanolite.co. Handling may require proportionate identity verification and consideration of relevant record-keeping obligations.'),('Links and the app','Links to research publications, other websites and app platforms take you to independently operated services. Their privacy practices apply there. Nanolite app notices describe app-specific processing separately.'),('Updates','This notice reflects the current website. We will update it if website features or data handling change. Last updated: 11 October 2026.')]
page('privacy.html','Global website privacy policy',intro('Privacy / Nanolite Global','Website privacy policy.','Information about this website and how inquiries are handled.')+'<article class="wrap policy-content">'+''.join(f'<section><h2>{e(title)}</h2><p>{e(text)}</p>'+('<a class="text-link" href="https://www.cloudflare.com/privacypolicy/">Cloudflare privacy policy ↗</a>' if title=='Hosting and technical information' else '')+'</section>' for title,text in privacy_sections)+'</article>')
notices=json.loads((R/'tools/app-notices.json').read_text(encoding='utf-8'))
for key in ['privacy','terms','delete-account']:
 source=notices[key];title=clean(re.sub('<[^>]+>','',re.search(r'<h1[^>]*>(.*?)</h1>',source,re.S)[1]));sections=''.join(re.findall(r'<section>[\s\S]*?</section>',source));warning=re.search(r'<aside>(.*?)</aside>',source,re.S)[1]
 page('app-'+key+'.html',title,intro('Nanolite app / Legal information',title,'Updated 11 October 2026')+f'<article class="wrap policy-content"><p class="notice">{warning}</p><nav class="policy-nav"><a href="app-privacy.html">Privacy policy</a><a href="app-terms.html">Terms</a><a href="app-delete-account.html">Account & data deletion</a></nav>{sections}</article>')
# Keep the original site's route names available alongside the established preview links.
for old,new in [('aboutus','about'),('contactus','contact'),('askourexperts','experts'),('productionorderrequestform','request'),('investor','investors')]:shutil.copyfile(R/(new+'.html'),R/(old+'.html'))
print('Generated static homepage, 13 detailed product pages, company pages, careers, investors, resources and request flow.')
